 '7d8092ac-96ae-4bb0-8f0e-696f96bfb218'::uuid, 'Globalization refers to the multiplicity of linkages and interconnections between states and societies making events in one place affect distant parts of the globe.', TRUE, 1),('c68dc7ee-6d93-43a7-8a94-ab4a1a218e46'::uuid, '7d8092ac-96ae-4bb0-8f0e-696f96bfb218'::uuid, 'Globalization is solely the spread of western politics to developing countries.', FALSE, 2),('591e567a-611e-48b7-8310-a8a489cca3da'::uuid, '7d8092ac-96ae-4bb0-8f0e-696f96bfb218'::uuid, 'Globalization means the end of national governments and rise of a single world government.', FALSE, 3),('bdea81ba-5d6e-4f30-88ed-b54ee5946645'::uuid, 'ed282503-fc90-4d80-8215-bb951978bf5d'::uuid, 'Political dimensions', FALSE, 0),('8a4e29fd-cb91-49b5-8d00-9199dcb144f3'::uuid, 'ed282503-fc90-4d80-8215-bb951978bf5d'::uuid, 'Economic dimensions', FALSE, 1),('d0ef03f6-a283-4444-8ccb-ab448245af8c'::uuid, 'ed282503-fc90-4d80-8215-bb951978bf5d'::uuid, 'Astronomical dimensions', TRUE, 2),('da019b1e-32d4-40d5-8325-db7ae0d1da42'::uuid, 'ed282503-fc90-4d80-8215-bb951978bf5d'::uuid, 'Cultural dimensions', FALSE, 3),('7d2ce8b0-9cc4-4e84-8944-b6c14881286e'::uuid, '7d8f7333-be92-4c90-8249-b4bf9a8a1c84'::uuid, 'The spread of local cultures across a single nation', FALSE, 0),('745dcd03-41b1-4c16-8851-e4ba9b6ab7db'::uuid, '7d8f7333-be92-4c90-8249-b4bf9a8a1c84'::uuid, 'The increasing interdependence of world economies through cross-border trade, capital flows and technologies', TRUE, 1),('2ff85f66-de00-4db2-8dc0-85479afab893'::uuid, '7d8f7333-be92-4c90-8249-b4bf9a8a1c84'::uuid, 'The disappearance of all national borders', FALSE, 2),('02f2b505-612d-4f65-86f5-c3284e542a7f'::uuid, '7d8f7333-be92-4c90-8249-b4bf9a8a1c84'::uuid, 'An emphasis on local markets only', FALSE, 3),('1c023567-e7d2-4525-815d-9925de6112a8'::uuid, 'b19d2c86-2dd8-4a40-8633-ce256babc416'::uuid, 'It eliminates all local traditions instantly', FALSE, 0),('8a692125-f4d0-4350-8207-a3dcca491fce'::uuid, 'b19d2c86-2dd8-4a40-8633-ce